<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Definition\Relation\Identity;

use SqlSemantics\Dialect;
use SqlSemantics\Model\Validation\InvalidStructure;
use SqlSemantics\Type\TypeDescriptor;

/**
 * Declares the integer type of an identity sequence.
 * @visibility public
 * @example Reading the sequence type
 *     $statement = (new \SqlSemantics\Binder((new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::PostgreSql))->build('CREATE TABLE t(id INTEGER)')))->bind('ALTER TABLE t ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (AS smallint)');
 *     $statement->actions[0]->options[0]->type->name // => 'smallint'
 */
final class SequenceStorage
{
    /**
     * @throws InvalidStructure
     */
    public function __construct(public readonly TypeDescriptor $type)
    {
        if ($type->dialect !== Dialect::PostgreSql) {
            throw new InvalidStructure('A sequence type requires a PostgreSQL type declaration.');
        }
    }
}
